namespace sv_c83bce1d5a064ed0ace3bd3e84e49b09.Models;

// Service contract records
public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

// Mutable form models for two-way binding
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";

    public PersonalInfo ToRecord() => new(FullName, Email, Phone, Address);
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";

    public WorkEntry ToRecord() => new(Company, Title, StartDate ?? DateTime.Today, IsCurrent ? null : EndDate, Description);
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";

    public Reference ToRecord() => new(Name, Relationship, Email, Phone);
}

@namespace sv_c83bce1d5a064ed0ace3bd3e84e49b09.Components.Apply

<nav aria-label="Application progress" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between position-relative px-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCurrent = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var isFuture = !isCurrent && !isCompleted;

            <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
                role="listitem">
                @if (isCompleted)
                {
                    <button class="btn step-circle bg-success text-white border-0 rounded-circle mx-auto d-flex align-items-center justify-content-center"
                            @onclick="() => OnStepClicked.InvokeAsync(step)"
                            aria-label="@($"Go back to {StepNames[i]}")">
                        <span>&#10003;</span>
                    </button>
                }
                else
                {
                    <div class="step-circle rounded-circle mx-auto d-flex align-items-center justify-content-center
                                @(isCurrent ? "bg-primary text-white" : "bg-light text-muted border")">
                        <span>@step</span>
                    </div>
                }
                <small class="d-block mt-1 @(isFuture ? "text-muted" : "") @(isCurrent ? "fw-bold" : "")">
                    @StepNames[i]
                </small>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

.step-circle {
    width: 40px;
    height: 40px;
    font-size: 1rem;
    cursor: default;
}

button.step-circle {
    cursor: pointer;
}

button.step-circle:hover {
    opacity: 0.85;
}

@namespace sv_c83bce1d5a064ed0ace3bd3e84e49b09.Components.Apply
@using sv_c83bce1d5a064ed0ace3bd3e84e49b09.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @Index</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Full Name</label>
                <input class="form-control" @bind="Reference.Name" @bind:event="oninput" placeholder="Reference name" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship</label>
                <input class="form-control" @bind="Reference.Relationship" @bind:event="oninput" placeholder="e.g. Former Manager" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="Reference.Email" @bind:event="oninput" placeholder="email@example.com" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone</label>
                <input type="tel" class="form-control" @bind="Reference.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_c83bce1d5a064ed0ace3bd3e84e49b09.Components.Apply
@using sv_c83bce1d5a064ed0ace3bd3e84e49b09.Models
@inject IApplicationService ApplicationService

<div>
    <h4 class="mb-3">Personal Information</h4>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input class="form-control @(validationErrors.Contains("FullName") ? "is-invalid" : "")"
                   @bind="Model.FullName" @bind:event="oninput" placeholder="John Doe" />
            @if (validationErrors.Contains("FullName"))
            {
                <div class="invalid-feedback">Full name is required.</div>
            }
        </div>
        <div class="col-md-6">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input type="email"
                   class="form-control @(validationErrors.Contains("Email") ? "is-invalid" : "")"
                   @bind="Model.Email" @bind:event="oninput" placeholder="email@example.com" />
            @if (validationErrors.Contains("Email"))
            {
                <div class="invalid-feedback">@emailError</div>
            }
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input type="tel"
                   class="form-control @(validationErrors.Contains("Phone") ? "is-invalid" : "")"
                   @bind="Model.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
            @if (validationErrors.Contains("Phone"))
            {
                <div class="invalid-feedback">Phone number is required.</div>
            }
        </div>
        <div class="col-md-6">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <input class="form-control @(validationErrors.Contains("Address") ? "is-invalid" : "")"
                   @bind="Model.Address" @bind:event="oninput" placeholder="123 Main St, City, State" />
            @if (validationErrors.Contains("Address"))
            {
                <div class="invalid-feedback">Address is required.</div>
            }
        </div>
    </div>

    <div class="d-flex justify-content-end mt-4">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @if (isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private HashSet<string> validationErrors = new();
    private string? errorMessage;
    private string emailError = "Email is required.";
    private bool isValidating;

    private async Task HandleNext()
    {
        validationErrors.Clear();
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName)) validationErrors.Add("FullName");
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            emailError = "Email is required.";
            validationErrors.Add("Email");
        }
        if (string.IsNullOrWhiteSpace(Model.Phone)) validationErrors.Add("Phone");
        if (string.IsNullOrWhiteSpace(Model.Address)) validationErrors.Add("Address");

        if (validationErrors.Count > 0) return;

        // Validate email via service
        isValidating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                emailError = "This email address is not valid.";
                validationErrors.Add("Email");
                return;
            }
        }
        catch
        {
            errorMessage = "Unable to validate email. Please try again.";
            return;
        }
        finally
        {
            isValidating = false;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_c83bce1d5a064ed0ace3bd3e84e49b09.Components.Apply
@using sv_c83bce1d5a064ed0ace3bd3e84e49b09.Models

<div>
    <h4 class="mb-3">Work History</h4>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index + 1"
                       CanRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? errorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        // Validate at least one entry has required fields
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate is null)
            {
                errorMessage = "Each position must have a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_c83bce1d5a064ed0ace3bd3e84e49b09.Components.Apply
@using sv_c83bce1d5a064ed0ace3bd3e84e49b09.Models

<div>
    <h4 class="mb-3">References</h4>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]"
                       Index="index + 1"
                       CanRemove="References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? errorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                errorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_c83bce1d5a064ed0ace3bd3e84e49b09.Components.Apply
@using sv_c83bce1d5a064ed0ace3bd3e84e49b09.Models

<div>
    <h4 class="mb-3">Cover Letter</h4>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    <div class="mb-3">
        <textarea class="form-control @(hasError ? "is-invalid" : "")"
                  rows="12"
                  maxlength="@MaxLength"
                  @bind="CoverLetter"
                  @bind:event="oninput"
                  @bind:after="OnCoverLetterChanged"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="form-text text-end">
            @(CoverLetter?.Length ?? 0) / @MaxLength characters
        </div>
    </div>

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private string? errorMessage;
    private bool hasError;

    private async Task OnCoverLetterChanged()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
    }

    private async Task HandleNext()
    {
        errorMessage = null;
        hasError = false;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            errorMessage = "A cover letter is required.";
            hasError = true;
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_c83bce1d5a064ed0ace3bd3e84e49b09.Components.Apply
@using sv_c83bce1d5a064ed0ace3bd3e84e49b09.Models

<div>
    <h4 class="mb-3">Review Your Application</h4>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    @if (SubmittedId is not null)
    {
        <div class="alert alert-success text-center p-4">
            <h5 class="mb-2">&#10003; Application Submitted Successfully!</h5>
            <p class="mb-0">Your application ID is <strong>#@SubmittedId</strong>. Keep this for your records.</p>
        </div>
    }
    else
    {
        <!-- Personal Info Section -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6"><strong>Name:</strong> @PersonalInfo.FullName</div>
                    <div class="col-md-6"><strong>Email:</strong> @PersonalInfo.Email</div>
                    <div class="col-md-6"><strong>Phone:</strong> @PersonalInfo.Phone</div>
                    <div class="col-md-6"><strong>Address:</strong> @PersonalInfo.Address</div>
                </div>
            </div>
        </div>

        <!-- Work History Section -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            <div class="card-body">
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-3 pb-3 border-bottom last-no-border">
                        <div><strong>@entry.Title</strong> at @entry.Company</div>
                        <div class="text-muted small">
                            @entry.StartDate?.ToString("MMM yyyy") &ndash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                        </div>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <div class="mt-1">@entry.Description</div>
                        }
                    </div>
                }
            </div>
        </div>

        <!-- References Section -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            <div class="card-body">
                @foreach (var r in References)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email, @r.Phone
                    </div>
                }
            </div>
        </div>

        <!-- Cover Letter Section -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(4)">Edit</button>
            </div>
            <div class="card-body">
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>
        </div>

        <div class="d-flex justify-content-between mt-4">
            <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@isSubmitting">
                @if (isSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    <span>Submitting...</span>
